class WidthObservedR5(unittest.TestCase):
    def test_empty_returns_before_locale_validation(self):
        self.assertEqual(convert('',True,{'内部で使用する東アジア言語':'KOREAN'}),'')
    def test_non_japanese_locale_is_explicitly_unsupported(self):
        with self.assertRaises(Unsupported):convert('A',True,{'内部で使用する東アジア言語':'KOREAN'})
    def test_supplementary_is_not_silently_replaced(self):
        with self.assertRaises(Unsupported):convert('😀',True,{})
    def test_single_character_subcases_from_observations(self):
        for src,half,full in [('ガ','ｶﾞ','ガ'),('パ','ﾊﾟ','パ'),('①','①','①'),('㍑','㍑','㍑'),('㎏','㎏','㎏'),('ー','ｰ','ー'),('Ａ','A','Ａ')]:
            self.assertEqual(convert(src,False,{}),half);self.assertEqual(convert(src,True,{}),full)
    def test_repeated_and_roundtrip_conversion(self):
        for src,half,full in zip(INPUTS[:10],NARROW[:10],WIDE[:10]):
            self.assertEqual(convert(half,False,{}),half);self.assertEqual(convert(full,True,{}),full)
            self.assertEqual(convert(half,True,{}),full);self.assertEqual(convert(full,False,{}),half)
for index in range(12):
    for full,expected in [(False,NARROW[index]),(True,WIDE[index])]:
        def test(self,index=index,full=full,expected=expected):self.assertEqual(convert(INPUTS[index],full,{}),expected)
        setattr(WidthObservedR5,f'test_run04_{"tofull" if full else "tohalf"}{index}',test)

class EagerArgumentsR5(unittest.TestCase):
    def make(self,source,mode='YES',headers='',analysis=False,warning='1'):
        t=tempfile.TemporaryDirectory();self.addCleanup(t.cleanup);root=Path(t.name)
        (root/'ERB').mkdir();(root/'CSV').mkdir()
        (root/'ERB/Different.ERB').write_text(source,encoding='utf-8-sig')
        (root/'ERB/Decl.ERH').write_text(headers,encoding='utf-8-sig')
        (root/'emuera.config').write_text('ロード時に引数を解析する:'+mode+'\n表示する最低警告レベル:'+warning+'\n',encoding='utf-8-sig')
        self.output=io.StringIO();p=Program(root,analysis_mode=analysis)
        self.vm=VM(p,GameData(root),Console([],self.output,no_wait=True),seed=123);return self.vm
    def test_unreached_three_warnings_are_structured_and_ordered(self):
        vm=self.make('@MAIN\nPRINTL finished\nRETURN\n@NEVER\nPRINTV 1+\nA="x"+1\nA=OTHER_MISSING()\nRETURN\n')
        d=vm.program.argument_diagnostics
        self.assertEqual([x.category for x in d],['E_SYNTAX','E_TYPE','E_FUNCTION'])
        self.assertEqual([x.location.line for x in d],[5,6,7]);self.assertEqual([x.display_order for x in d],[0,1,2])
        self.assertEqual([x.source_text for x in d],['PRINTV 1+','A="x"+1','A=OTHER_MISSING()'])
        vm.run('MAIN');output=self.output.getvalue()
        self.assertLess(output.index('Now Loading...'),output.index('警告Lv2:Different.ERB:5行目:'))
        self.assertLess(output.index('OTHER_MISSING()は') if 'OTHER_MISSING()は' in output else output.index('警告Lv2:Different.ERB:7行目:'),output.index('finished'))
        self.assertEqual(vm.eval('A'),0)
    def test_no_mode_unreached_lines_have_no_warnings(self):
        vm=self.make('@MAIN\nRETURN\n@NEVER\nPRINTV 1+\nA="x"+1\nA=MISSING()\nRETURN\n',mode='NO')
        self.assertEqual(vm.program.argument_diagnostics,[]);vm.run('MAIN');self.assertNotIn('警告',self.output.getvalue())
    def test_reached_error_marks_line_before_side_effects(self):
        vm=self.make('@MAIN\nA=SIDE()+"x"\nRETURN\n@SIDE\n#FUNCTION\nB+=1\nRETURNF 1\n')
        with self.assertRaises(EraError) as c:vm.run('MAIN')
        self.assertEqual((c.exception.code,c.exception.location.line),('E_TYPE',2));self.assertEqual(vm.eval('B'),0)
    def test_no_reached_syntax_still_fails_at_runtime(self):
        vm=self.make('@MAIN\nPRINTV 1+\nRETURN\n',mode='NO')
        with self.assertRaises(EraError) as c:vm.run('MAIN')
        self.assertEqual(c.exception.code,'E_SYNTAX')
    def test_static_parsing_does_not_evaluate_functions_or_rng(self):
        source='@MAIN\nA:NEXT()=SIDE()+RAND:100\nSTR = n{SIDE()}\nRETURN\n@NEXT\n#FUNCTION\nB+=1\nRETURNF 0\n@SIDE\n#FUNCTION\nC+=1\nRETURNF 9\n'
        with patch.object(VM,'eval',side_effect=AssertionError('static evaluation')):
            vm=self.make(source)
        baseline=self.make(source,mode='NO')
        self.assertEqual(vm.rng.getstate(),baseline.rng.getstate())
        for n in ['A','B','C','STR']:self.assertEqual(vm.data.variables[n].values,baseline.data.variables[n].values)
        self.assertEqual(vm.frames,[]);self.assertEqual(vm.program.argument_diagnostics,[])
    def test_dynamic_index_not_frozen_by_ast_cache(self):
        vm=self.make('@MAIN\nB=2\nA:B=9\nB=3\nA:B=7\nRETURN\n');vm.run('MAIN')
        self.assertEqual((vm.eval('A:2'),vm.eval('A:3')),(9,7))
    def test_private_and_argument_types_not_values_are_inspected(self):
        vm=self.make('@MAIN\nCALL SUB,5\nRETURN\n@SUB,ARG:0\n#DIM Q_PRIVATE\nQ_PRIVATE=ARG:0\nPRINTV Q_PRIVATE\nRETURN\n')
        self.assertEqual(vm.program.argument_diagnostics,[]);vm.run('MAIN');self.assertIn('5',self.output.getvalue())
    def test_bad_arity_is_static_diagnostic(self):
        vm=self.make('@MAIN\nRETURN\n@NEVER\nA=STRLENS()\nRETURN\n')
        self.assertEqual(vm.program.argument_diagnostics[0].category,'E_ARGUMENT')
    def test_warning_display_filter_does_not_clear_line_error(self):
        vm=self.make('@MAIN\nPRINTV 1+\nRETURN\n',warning='3')
        with self.assertRaises(EraError):vm.run('MAIN')
        self.assertNotIn('警告',self.output.getvalue());self.assertEqual(len(vm.program.argument_diagnostics),1)
    def test_analysis_mode_is_separate_trigger(self):
        vm=self.make('@MAIN\nRETURN\n@NEVER\nPRINTV 1+\nRETURN\n',mode='NO',analysis=True)
        self.assertEqual(len(vm.program.argument_diagnostics),1);self.assertEqual(vm.program.argument_coverage[1]['trigger'],'AnalysisMode')
    def test_fatal_unmatched_block_not_downgraded(self):
        for mode in ['YES','NO']:
            with self.assertRaises(EraError):self.make('@MAIN\nIF 1\nRETURN\n',mode=mode)
    def test_case_nested_strings_and_multiple_conditions_eager(self):
        vm=self.make('@MAIN\nSELECTCASE "GO TO X"\nCASE "NO",("GO TO X")\nA=1\nCASEELSE\nA=2\nENDSELECT\nRETURN\n')
        self.assertEqual(vm.program.argument_diagnostics,[]);vm.run('MAIN');self.assertEqual(vm.eval('A'),1)
    def test_form_width_wrong_type_is_static_without_value_evaluation(self):
        vm=self.make('@MAIN\nRETURN\n@NEVER\nPRINTFORML {1,"x"}\nRETURN\n')
        self.assertEqual(vm.program.argument_diagnostics[0].category,'E_TYPE')
    def test_statement_array_increment_binds_to_lvalue(self):
        vm=self.make('@MAIN\nLOCAL:1 ++\nLOCAL:1 --\nA:2++\nRETURN\n')
        self.assertEqual(vm.program.argument_diagnostics,[]);vm.run('MAIN')
        self.assertEqual(vm.eval('A:2'),1)
    def test_dynamic_string_csv_index_has_static_string_contract(self):
        vm=self.make('@MAIN\nRETURN\n@NEVER\nA=TALENT:(ARGS)\nRETURN\n')
        self.assertEqual(vm.program.argument_diagnostics,[])
    def test_power_command_is_distinct_from_two_argument_function(self):
        # This test is the load-parser contract. The pre-existing POWER
        # command runtime fallback gap is separately recorded for run05.
        vm=self.make('@MAIN\nB=POWER(2,3)\nRETURN\n@UNREACHED\nPOWER A,2,3\nRETURN\n')
        self.assertEqual(vm.program.argument_diagnostics,[]);vm.run('MAIN')
        self.assertEqual(vm.eval('B'),8)

class OracleEncodingR5(unittest.TestCase):
    def test_utf16_and_utf8_read_without_loss(self):
        with tempfile.TemporaryDirectory() as td:
            for codec in ['utf-16','utf-8','utf-8-sig']:
                p=Path(td)/codec;p.write_bytes('ORACLE|unicode|str|Á①カ\u3099Ａ\u0301  \r\n'.encode(codec))
                self.assertEqual(markers(read_text(p)),['ORACLE|unicode|str|Á①カ\u3099Ａ\u0301  '])
    def test_explicit_utf8_json_independent_of_cp932_open_defaults(self):
        with tempfile.TemporaryDirectory() as td:
            p=Path(td)/'comparison.json';value={'str':'Á①カ\u3099Ａ\u0301  '}
            write_json_exclusive(p,value);self.assertEqual(json.loads(p.read_bytes().decode('utf-8')),value)
            with self.assertRaises(UnicodeEncodeError):value['str'].encode('cp932')
    def test_existing_evidence_never_truncated(self):
        with tempfile.TemporaryDirectory() as td:
            p=Path(td)/'comparison.json';p.write_bytes(b'previous')
            with self.assertRaises(FileExistsError):write_json_exclusive(p,{'new':1})
            self.assertEqual(p.read_bytes(),b'previous')
    def test_encoding_failure_does_not_create_empty_file(self):
        with tempfile.TemporaryDirectory() as td:
            p=Path(td)/'comparison.json'
            with self.assertRaises(UnicodeEncodeError):write_json_exclusive(p,{'bad':'\ud800'})
            self.assertFalse(p.exists())
    def test_padding_mismatch_is_physical_only(self):
        r='ORACLE|x|str|①\nORACLE|end\n';s='ORACLE|x|str|① \nORACLE|end\n'
        j=observations(r,r,s,['x','end']);self.assertTrue(j['marker_observations_equal']);self.assertFalse(j['physical_marker_observations_equal'])
    def test_logical_spaces_are_never_trimmed(self):
        j=observations('ORACLE|x|str|a \n','ORACLE|x|str|a\n','',['x']);self.assertFalse(j['marker_observations_equal'])
    def test_incomplete_or_duplicate_capture_is_not_complete(self):
        j=observations('ORACLE|x\nORACLE|x\n','ORACLE|x\nORACLE|x\n','',['x','end']);self.assertFalse(j['unique_ids_complete'])
    def test_combining_marks_not_normalized(self):
        j=observations('ORACLE|x|str|Á\n','ORACLE|x|str|A\u0301\n','',['x']);self.assertFalse(j['marker_observations_equal'])
